Texture2D g_modelBaseColor : register(t6);
Texture2D g_modelMetalRough : register(t7);
SamplerState g_sampler : register(s0);

cbuffer cbEffect : register(b0)
{
    float g_time;
    float g_audioBass;
    float g_audioMid;
    float g_audioTreble;
    float4 g_params[16];
};

cbuffer cbRaymarchCamera : register(b3)
{
    float3 g_camPos;
    float  _camPad;
    row_major float4x4 g_invViewProj; 
    row_major float4x4 g_viewProj;
};


cbuffer cbMaterial : register(b5)
{
    float4 g_baseColorRate;
    float  g_metallicRate;
    float  g_roughnessRate;
	float  g_hasNormalMap;   
    float _matPad;
};


struct PS_IN {
    float4 pos : SV_Position;
    float2 uv : TEXCOORD0;
    float3 normal : NORMAL;
    float3 viewNormal : NORMAL1;
    float3 worldNormal : NORMAL2;
    float3 worldPos : POSITION1;
    float3 worldTangent : TANGENT;
    nointerpolation uint instID : INSTANCEID;
};

struct PS_OUT {
    float4 target0 : SV_Target0;
    float4 target1 : SV_Target1;
    float4 target2 : SV_Target2;
    float4 target3 : SV_Target3;
    float4 target4 : SV_Target4;
};

PS_OUT main(PS_IN In)
{
    float4 node2_out = float4(1.000000f, 0.481250f, 0.481250f, 1.000000f);
    float node50_out = 2.000000f;
    float node5_out = g_time;
    float node43_out = 3.200000f;
    float4 node45_out = ((float4)(node43_out)) * ((float4)(node5_out));
    float4 node53_out = frac(node45_out);
    float node52_out = 6.283185f;
    float4 node54_out = ((float4)(node52_out)) * node53_out;
    float4 node21_out = sin(node54_out);
    float node48_out = 1.600000f;
    float4 node49_out = ((float4)(node48_out)) + node21_out;
    float4 node51_out = node49_out / ((float4)(node50_out));
    float4 node27_out = node51_out;
    float4 node24_out = ((float4)(node27_out.x)) * node2_out;
    float4 node4_out = (g_modelBaseColor.Sample(g_sampler, In.uv) * g_baseColorRate);
    float4 node47_out = node4_out * node24_out;
    float4 node55_out = float4(0.000000f, 0.000000f, 0.000000f, 1.000000f);
    PS_OUT o;
    o.target0 = float4((node47_out).xyz, (g_modelMetalRough.Sample(g_sampler, In.uv).b * g_metallicRate));
    o.target1 = float4((normalize(In.worldNormal)) * 0.5 + 0.5, (g_modelMetalRough.Sample(g_sampler, In.uv).g * g_roughnessRate));
    o.target2 = float4(In.worldPos, 1.0);
    o.target3 = float4((node47_out).xyz, 1.0);
    o.target4 = node55_out;
    return o;
}

